package com.nexamart.backend.api;import com.nexamart.backend.api.ApiModels.*;import com.nexamart.backend.domain.OrderStatus;import com.nexamart.backend.service.DeliveryService;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.time.Instant;
@RestController @RequestMapping("/api/v1/delivery")public class DeliveryController{final DeliveryService s;public DeliveryController(DeliveryService s){this.s=s;}@GetMapping("/dashboard")DeliveryDashboardResponse dashboard(){return s.dashboard();}@GetMapping("/orders")PageResponse<OrderResponse> orders(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int pageSize,@RequestParam(required=false)String search,@RequestParam(required=false)String status,@RequestParam(required=false)Instant fromDate,@RequestParam(required=false)Instant toDate){return s.orders(page,pageSize,search,status==null?null:OrderStatus.valueOf(status),fromDate,toDate);}@GetMapping("/orders/{id}")OrderResponse detail(@PathVariable Long id){return s.detail(id);}@PatchMapping("/orders/{id}/action")ResponseEntity<Void> action(@PathVariable Long id,@RequestBody ActionRequest r){s.action(id,r);return ResponseEntity.noContent().build();}
 @GetMapping("/availability")AvailabilityResponse availability(){return s.availability();}@PutMapping("/availability")AvailabilityResponse availability(@RequestBody AvailabilityRequest r){return s.updateAvailability(r);}
 @PutMapping("/location") ResponseEntity<Void> location(@RequestBody LocationUpdateRequest r){s.updateLocation(r.latitude(),r.longitude());return ResponseEntity.noContent().build();}
 @GetMapping("/profile")ProfileResponse profile(){return s.profile();}@PutMapping("/profile")ProfileResponse profile(@RequestBody ProfileUpdate r){return s.updateProfile(r);}
 @GetMapping("/notifications")PageResponse<NotificationResponse> notifications(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int pageSize,@RequestParam(defaultValue="false")boolean unreadOnly){return s.notifications(page,pageSize,unreadOnly);}@PostMapping("/notifications/{id}/read")ResponseEntity<Void> read(@PathVariable Long id){s.markRead(id);return ResponseEntity.noContent().build();}@PostMapping("/notifications/read-all")ResponseEntity<Void> readAll(){s.markAllRead();return ResponseEntity.noContent().build();}
 @GetMapping("/earnings/summary")EarningsSummary earningsSummary(@RequestParam(required=false)Instant fromDate,@RequestParam(required=false)Instant toDate){return s.earningsSummary(fromDate,toDate);}@GetMapping("/earnings")PageResponse<EarningResponse> earnings(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int pageSize){return s.earningHistory(page,pageSize);}}
